{
  "case_id": "xsu_sg_011_doctor_certificate",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Svaret siger, at Udbetaling Danmark kan indhente lægeattest fra den praktiserende læge, når funktionsniveauet ikke kan vurderes ud fra dokumentationen. Det beskriver attestens indhold korrekt og stemmer med rubrikken og vejledningens afsnit 5.1.2. Ingen af de væsentlige fejl fra rubrikken forekommer."},
    "c02_required_elements_complete": {"label": "met", "reason": "Alle tre kritiske elementer er med: mulighed for at indhente attest fra den praktiserende læge, funktionsevne i forhold til den ansøgte funktionsnedsættelse, og behov for fortsat behandling eller henvisning til yderligere udredning eller behandling hos en specialist."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer begge dele af spørgsmålet: hvad Udbetaling Danmark kan gøre, og hvad attesten skal beskrive."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde (hverken bestemmelse eller vejledningsafsnit), så de juridiske udsagn kan ikke henføres til en kilde i selve svaret."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde i svaret, så kildens gyldighed kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde i svaret, så det kan ikke vurderes, om kilden understøtter påstandene."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Svaret tilføjer ingen regler, betingelser eller myndigheder ud over dem, der står i vejledningens afsnit 5.1.2. Indholdet svarer til det, kilden siger."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "Svaret bruger 'kan anmode' og gør dermed attestindhentning til en mulighed og ikke en automatisk pligt, og betingelsen om utilstrækkelig dokumentation er med. Fremmødeforbehold kræves kun, hvis fremmøde omtales, og det gør svaret ikke."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er kort og sammenhængende: betingelsen, muligheden og attestens indhold hænger logisk sammen uden indbyrdes modsigelser."},
    "c10_legal_modality_precision": {"label": "met", "reason": "'Kan' er brugt om Udbetaling Danmarks mulighed, og 'skal' er brugt om attestens indhold. Det følger kilden, og intet bliver gjort absolut."}
  },
  "xhaile_coverage": {
    "A61": {"label": "yes", "reason": "Svaret dækker, at attest kan indhentes ved utilstrækkelig dokumentation, og at den skal omfatte funktionsevne og behov for behandling eller henvisning. De supplerende forhold (fremmøde, journaloplysninger, udgifter) er ikke nævnt, men de er kun supplerende ifølge rubrikken."}
  },
  "overall_notes": "Indholdet er juridisk korrekt og komplet i forhold til rubrikkens kritiske elementer. Svaret nævner ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable efter kilderegelen."
}

